SELECT c.city, CASE WHEN c.credit_limit >= 13200 THEN 'high' WHEN c.credit_limit >= 2500 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, ROUND(AVG(a.balance), 2) AS avg_balance FROM accounts a INNER JOIN customers c ON a.customer_id = c.id GROUP BY c.city, CASE WHEN c.credit_limit >= 13200 THEN 'high' WHEN c.credit_limit >= 2500 THEN 'mid' ELSE 'low' END HAVING ROUND(AVG(a.balance), 2) >= 75;
